   "main": "// Opcode's cartridge inspector. Provided by the course.\n// It reads game.nes (choose it with the Cartridge menu) and shows what\n// your Cartridge class makes of it.\n#include <cstdint>\n#include <cstdio>\n#include <fstream>\n#include <iterator>\n#include <vector>\n#include \"cart.h\"\n\nnamespace {\n\n// Read a whole file into memory. Empty if it cannot be read.\nstd::vector<std::uint8_t> read_file(const char* name) {\n    std::ifstream f(name, std::ios::binary);\n    return std::vector<std::uint8_t>(std::istreambuf_iterator<char>(f), std::istreambuf_iterator<char>());\n}\n\nconst char* result_name(LoadResult r) {\n    switch (r) {\n    case LoadResult::Ok: return \"Ok\";\n    case LoadResult::NotInes: return \"NotInes\";\n    case LoadResult::TooShort: return \"TooShort\";\n    case LoadResult::UnsupportedMapper: return \"UnsupportedMapper\";\n    }\n    return \"an unknown result\";\n}\n\n// Read game.nes and plug it into cart. Prints a message and returns false\n// if that does not work.\nbool plug_in_cartridge(Cartridge& cart) {\n    std::vector<std::uint8_t> data = read_file(\"game.nes\");\n    if (data.empty()) {\n        std::printf(\"Could not read the cartridge file.\\n\");\n        return false;\n    }\n    LoadResult r = cart.load(data);\n    if (r == LoadResult::UnsupportedMapper) {\n        int mapper = data.size() >= 8 ? ((data[7] & 0xF0) | (data[6] >> 4)) : -1;\n        std::printf(\"This cartridge uses mapper %d, which your emulator does not have yet.\\n\", mapper);\n        return false;\n    }\n    if (r != LoadResult::Ok) {\n        std::printf(\"Cartridge::load could not read this cartridge (it returned LoadResult::%s).\\n\", result_name(r));\n        return false;\n    }\n    return true;\n}\n\n}  // namespace\n\nint main() {\n    std::vector<std::uint8_t> data = read_file(\"game.nes\");\n    if (data.empty()) {\n        std::printf(\"Could not read the cartridge file.\\n\");\n        return 1;\n    }\n    std::printf(\"File size: %zu bytes\\n\", data.size());\n    Cartridge cart;\n    LoadResult r = cart.load(data);\n    std::printf(\"load returned LoadResult::%s\\n\", result_name(r));\n    if (r != LoadResult::Ok) return 0;\n    std::printf(\"Mapper:     %d\\n\", cart.mapper());\n    std::printf(\"PRG ROM:    %d x 16 KB\\n\", cart.prg_banks());\n    if (cart.chr_banks()) std::printf(\"CHR ROM:    %d x 8 KB\\n\", cart.chr_banks());\n    else std::printf(\"CHR:        8 KB of CHR RAM\\n\");\n    std::printf(\"Mirroring:  %s\\n\", cart.mirroring() == Mirroring::Vertical ? \"vertical\" : \"horizontal\");\n    std::printf(\"Battery:    %s\\n\", cart.has_battery() ? \"yes\" : \"no\");\n}\n",
