   "solution": {
    "cart.cpp": "#include \"cart.h\"\n\nLoadResult Cartridge::load(const std::vector<std::uint8_t>& file) {\n    if (file.size() < 16) {\n        return LoadResult::TooShort;\n    }\n    if (file[0] != 'N' || file[1] != 'E' || file[2] != 'S' || file[3] != 0x1A) {\n        return LoadResult::NotInes;\n    }\n    int new_prg_banks = file[4];\n    int new_chr_banks = file[5];\n    std::uint8_t flags6 = file[6];\n    std::uint8_t flags7 = file[7];\n    std::size_t trainer = (flags6 & 0x04) ? 512 : 0;\n    std::size_t needed = 16 + trainer + new_prg_banks * 0x4000 + new_chr_banks * 0x2000;\n    if (file.size() < needed) {\n        return LoadResult::TooShort;\n    }\n    int new_mapper = (flags7 & 0xF0) | (flags6 >> 4);\n    if (new_mapper != 0) {\n        return LoadResult::UnsupportedMapper;\n    }\n\n    // Copy the ROMs into memory of our own, replacing any earlier cartridge.\n    auto rom = file.begin() + 16 + trainer;\n    auto chr_start = rom + new_prg_banks * 0x4000;\n    prg_.assign(rom, chr_start);\n    if (new_chr_banks) {\n        chr_.assign(chr_start, chr_start + new_chr_banks * 0x2000);\n    } else {\n        chr_.assign(0x2000, 0);                     // 8 KB of CHR RAM, cleared\n    }\n    chr_is_ram_ = new_chr_banks == 0;\n    prg_ram_.fill(0);\n\n    mapper_ = new_mapper;\n    prg_banks_ = new_prg_banks;\n    chr_banks_ = new_chr_banks;\n    mirroring_ = (flags6 & 0x01) ? Mirroring::Vertical : Mirroring::Horizontal;\n    battery_ = (flags6 & 0x02) != 0;\n    return LoadResult::Ok;\n}\n\nstd::uint8_t Cartridge::cpu_read(std::uint16_t addr) {\n    if (addr >= 0x6000 && addr < 0x8000) {\n        return prg_ram_[addr - 0x6000];\n    }\n    if (addr >= 0x8000 && !prg_.empty()) {\n        return prg_[(addr - 0x8000) % prg_.size()];\n    }\n    return 0;\n}\n\nvoid Cartridge::cpu_write(std::uint16_t addr, std::uint8_t value) {\n    if (addr >= 0x6000 && addr < 0x8000) {\n        prg_ram_[addr - 0x6000] = value;\n    }\n}\n\nstd::uint8_t Cartridge::ppu_read(std::uint16_t addr) {\n    if (chr_.empty()) {\n        return 0;\n    }\n    return chr_[addr & 0x1FFF];\n}\n\nvoid Cartridge::ppu_write(std::uint16_t addr, std::uint8_t value) {\n    if (chr_is_ram_) {\n        chr_[addr & 0x1FFF] = value;\n    }\n}\n"
   },
   "harness": "#include <array>\n#include <cstdint>\n#include <cstdio>\n#include <fstream>\n#include <iostream>\n#include <iterator>\n#include <vector>\n#include \"cart.h\"\nnamespace {\n\n// Builds a small iNES file in memory for the tests.\nstd::vector<std::uint8_t> make_rom(int prg_banks, int chr_banks, std::uint8_t flags6, std::uint8_t flags7) {\n    std::vector<std::uint8_t> f(16, 0);\n    f[0] = 'N'; f[1] = 'E'; f[2] = 'S'; f[3] = 0x1A;\n    f[4] = static_cast<std::uint8_t>(prg_banks);\n    f[5] = static_cast<std::uint8_t>(chr_banks);\n    f[6] = flags6;\n    f[7] = flags7;\n    if (flags6 & 0x04) f.resize(16 + 512, 0);\n    for (long i = 0; i < prg_banks * 0x4000L; i++) f.push_back(static_cast<std::uint8_t>(i * 7 + (i >> 8)));\n    for (long i = 0; i < chr_banks * 0x2000L; i++) f.push_back(static_cast<std::uint8_t>(0xA0 ^ i ^ (i >> 4)));\n    return f;\n}\n\nstd::vector<std::uint8_t> read_file(const char* name) {\n    std::ifstream f(name, std::ios::binary);\n    return std::vector<std::uint8_t>(std::istreambuf_iterator<char>(f), std::istreambuf_iterator<char>());\n}\n\nconst char* result_name(LoadResult r) {\n    switch (r) {\n    case LoadResult::Ok: return \"Ok\";\n    case LoadResult::NotInes: return \"NotInes\";\n    case LoadResult::TooShort: return \"TooShort\";\n    case LoadResult::UnsupportedMapper: return \"UnsupportedMapper\";\n    }\n    return \"?\";\n}\n\n}  // namespace\n\nCartridge cart;\n\nint main() {\n    int t = 0;\n    if (!(std::cin >> t)) return 1;\n    auto show4 = [](std::uint16_t a, std::uint16_t b, std::uint16_t c, std::uint16_t d) {\n        std::printf(\"%02X \", cart.cpu_read(a)); std::printf(\"%02X \", cart.cpu_read(b));\n        std::printf(\"%02X \", cart.cpu_read(c)); std::printf(\"%02X\\n\", cart.cpu_read(d));\n    };\n    if (t == 1) {\n        std::printf(\"load %s\\n\", result_name(cart.load(make_rom(1, 1, 0, 0))));\n        show4(0x8000, 0x8123, 0xC123, 0xFFFF);\n    }\n    if (t == 2) {\n        std::printf(\"load %s\\n\", result_name(cart.load(make_rom(2, 1, 0, 0))));\n        show4(0x8000, 0x8123, 0xC123, 0xFFFF);\n    }\n    if (t == 3) {\n        std::printf(\"load %s\\n\", result_name(cart.load(make_rom(1, 1, 0, 0))));\n        cart.cpu_write(0x6000, 0x11);\n        cart.cpu_write(0x7FFF, 0x22);\n        cart.cpu_write(0x8000, 0x99);\n        show4(0x6000, 0x7FFF, 0x6001, 0x8000);\n    }\n    if (t == 4) {\n        std::printf(\"load %s\\n\", result_name(cart.load(make_rom(1, 1, 0, 0))));\n        std::printf(\"CHR ROM: %02X\", cart.ppu_read(0x0000));\n        std::printf(\" %02X\", cart.ppu_read(0x0011));\n        std::printf(\" %02X\", cart.ppu_read(0x1FFF));\n        cart.ppu_write(0x0000, 0x55);\n        std::printf(\" after a write: %02X\\n\", cart.ppu_read(0x0000));\n        std::printf(\"load %s\\n\", result_name(cart.load(make_rom(1, 0, 0, 0))));\n        std::printf(\"CHR RAM: %02X\", cart.ppu_read(0x0000));\n        cart.ppu_write(0x0000, 0x55);\n        cart.ppu_write(0x1FFF, 0x66);\n        std::printf(\" after writes: %02X\", cart.ppu_read(0x0000));\n        std::printf(\" %02X\\n\", cart.ppu_read(0x1FFF));\n    }\n    if (t == 5) {\n        std::printf(\"load %s\\n\", result_name(cart.load(make_rom(1, 1, 0, 0))));\n        std::uint8_t before = cart.cpu_read(0x8123);\n        std::printf(\"mapper 1: load %s\\n\", result_name(cart.load(make_rom(1, 1, 0x10, 0))));\n        std::printf(\"the first cartridge is still there: %s\\n\", cart.cpu_read(0x8123) == before ? \"yes\" : \"no\");\n        auto rom = make_rom(2, 1, 0, 0);\n        rom[16 + 0x123] = 0xEE;\n        std::printf(\"load %s\\n\", result_name(cart.load(rom)));\n        std::printf(\"the new one replaced it: %02X\\n\", cart.cpu_read(0x8123));\n    }\n    if (t == 6) {\n        LoadResult r = cart.load(read_file(\"nestest.nes\"));\n        std::printf(\"nestest: load %s, reset vector %02X\", result_name(r), cart.cpu_read(0xFFFD));\n        std::printf(\"%02X\\n\", cart.cpu_read(0xFFFC));\n    }\n}\n",
