   "harness": "#include <array>\n#include <cstdint>\n#include <cstdio>\n#include <fstream>\n#include <iostream>\n#include <iterator>\n#include <vector>\n#include \"cart.h\"\n#include \"ppu.h\"\nnamespace {\n\n// Builds a small iNES file in memory for the tests.\nstd::vector<std::uint8_t> make_rom(int prg_banks, int chr_banks, std::uint8_t flags6, std::uint8_t flags7) {\n    std::vector<std::uint8_t> f(16, 0);\n    f[0] = 'N'; f[1] = 'E'; f[2] = 'S'; f[3] = 0x1A;\n    f[4] = static_cast<std::uint8_t>(prg_banks);\n    f[5] = static_cast<std::uint8_t>(chr_banks);\n    f[6] = flags6;\n    f[7] = flags7;\n    if (flags6 & 0x04) f.resize(16 + 512, 0);\n    for (long i = 0; i < prg_banks * 0x4000L; i++) f.push_back(static_cast<std::uint8_t>(i * 7 + (i >> 8)));\n    for (long i = 0; i < chr_banks * 0x2000L; i++) f.push_back(static_cast<std::uint8_t>(0xA0 ^ i ^ (i >> 4)));\n    return f;\n}\n\nstd::vector<std::uint8_t> read_file(const char* name) {\n    std::ifstream f(name, std::ios::binary);\n    return std::vector<std::uint8_t>(std::istreambuf_iterator<char>(f), std::istreambuf_iterator<char>());\n}\n\nconst char* result_name(LoadResult r) {\n    switch (r) {\n    case LoadResult::Ok: return \"Ok\";\n    case LoadResult::NotInes: return \"NotInes\";\n    case LoadResult::TooShort: return \"TooShort\";\n    case LoadResult::UnsupportedMapper: return \"UnsupportedMapper\";\n    }\n    return \"?\";\n}\n\n}  // namespace\n\nCartridge cart;\nPpu ppu(cart);\n\nstatic void show_tile(std::uint16_t table, std::uint8_t tile) {\n    for (int row = 0; row < 8; row++) {\n        auto c = ppu.tile_row(table, tile, row);\n        for (int x = 0; x < 8; x++) std::printf(\"%d\", c[x]);\n        std::printf(\"\\n\");\n    }\n}\n\nint main() {\n    int t = 0;\n    if (!(std::cin >> t)) return 1;\n    if (t <= 2) {\n        cart.load(make_rom(1, 0, 0, 0));      // CHR RAM, so the test can draw tiles\n        ppu.reset();\n        // Tile 1 in table 0000: a diagonal of colour 1, a frame of colour 2, both: 3.\n        const std::uint8_t lo[8] = {0x81, 0x40, 0x20, 0x10, 0x08, 0x04, 0x02, 0x81};\n        const std::uint8_t hi[8] = {0xFF, 0x81, 0x81, 0x81, 0x81, 0x81, 0x81, 0xFF};\n        for (int i = 0; i < 8; i++) { ppu.write(static_cast<std::uint16_t>(0x0010 + i), lo[i]); ppu.write(static_cast<std::uint16_t>(0x0018 + i), hi[i]); }\n        // Tile FF in table 1000: only the low plane, a checkerboard.\n        for (int i = 0; i < 8; i++) ppu.write(static_cast<std::uint16_t>(0x1FF0 + i), (i & 1) ? 0x55 : 0xAA);\n        if (t == 1) { std::printf(\"tile 01 of table 0000:\\n\"); show_tile(0x0000, 0x01); }\n        if (t == 2) { std::printf(\"tile FF of table 1000:\\n\"); show_tile(0x1000, 0xFF); }\n    }\n    if (t == 3) {\n        cart.load(read_file(\"nestest.nes\"));\n        ppu.reset();\n        std::printf(\"nestest, tile 41 of table 0000:\\n\"); show_tile(0x0000, 0x41);\n        std::printf(\"nestest, tile 2A of table 0000:\\n\"); show_tile(0x0000, 0x2A);\n    }\n}\n",
