   "harness": "#include <array>\n#include <cstdint>\n#include <cstdio>\n#include <fstream>\n#include <iostream>\n#include <iterator>\n#include <vector>\n#include \"bus.h\"\n#include \"cart.h\"\n#include \"ppu.h\"\nnamespace {\n\n// Builds a small iNES file in memory for the tests.\nstd::vector<std::uint8_t> make_rom(int prg_banks, int chr_banks, std::uint8_t flags6, std::uint8_t flags7) {\n    std::vector<std::uint8_t> f(16, 0);\n    f[0] = 'N'; f[1] = 'E'; f[2] = 'S'; f[3] = 0x1A;\n    f[4] = static_cast<std::uint8_t>(prg_banks);\n    f[5] = static_cast<std::uint8_t>(chr_banks);\n    f[6] = flags6;\n    f[7] = flags7;\n    if (flags6 & 0x04) f.resize(16 + 512, 0);\n    for (long i = 0; i < prg_banks * 0x4000L; i++) f.push_back(static_cast<std::uint8_t>(i * 7 + (i >> 8)));\n    for (long i = 0; i < chr_banks * 0x2000L; i++) f.push_back(static_cast<std::uint8_t>(0xA0 ^ i ^ (i >> 4)));\n    return f;\n}\n\nstd::vector<std::uint8_t> read_file(const char* name) {\n    std::ifstream f(name, std::ios::binary);\n    return std::vector<std::uint8_t>(std::istreambuf_iterator<char>(f), std::istreambuf_iterator<char>());\n}\n\nconst char* result_name(LoadResult r) {\n    switch (r) {\n    case LoadResult::Ok: return \"Ok\";\n    case LoadResult::NotInes: return \"NotInes\";\n    case LoadResult::TooShort: return \"TooShort\";\n    case LoadResult::UnsupportedMapper: return \"UnsupportedMapper\";\n    }\n    return \"?\";\n}\n\n}  // namespace\n\nCartridge cart;\nPpu ppu(cart);\nBus bus(cart, ppu);\n\nstatic void peek(std::uint16_t a) { std::printf(\" %04X=%02X\", a, ppu.read(a)); }\n\nint main() {\n    int t = 0;\n    if (!(std::cin >> t)) return 1;\n    cart.load(make_rom(1, 0, 0x01, 0));\n    bus.reset();\n    ppu.reset();\n    if (t == 1) {\n        bus.write(0x2006, 0x3F); bus.write(0x2006, 0x00); bus.write(0x2007, 0x2A);\n        bus.write(0x3FFE, 0x21); bus.write(0x3FFE, 0x08); bus.write(0x3FFF, 0x33);\n        std::printf(\"PPU memory:\"); peek(0x3F00); peek(0x2108); std::printf(\"\\n\");\n    }\n    if (t == 2) {\n        bus.write(0x2003, 0x10); bus.write(0x2004, 0xAA); bus.write(0x2004, 0xBB);\n        bus.write(0x2003, 0x10);\n        std::uint8_t a = bus.read(0x2004), b = bus.read(0x2004);\n        bus.write(0x2003, 0x11);\n        std::printf(\"OAM: %02X %02X\", a, b);\n        std::printf(\" %02X\\n\", bus.read(0x2004));\n    }\n    if (t == 3) {\n        bus.write(0x2005, 0x12);\n        bus.write(0x2006, 0x34);\n        bus.write(0x2007, 0x5A);\n        std::printf(\"after one PPUSCROLL write, PPUADDR took the low byte: 0034=%02X\\n\", ppu.read(0x0034));\n        bus.read(0x2002);\n        bus.write(0x2006, 0x20); bus.write(0x2006, 0x10); bus.write(0x2007, 0x6B);\n        std::printf(\"after reading PPUSTATUS, both bytes again: 2010=%02X\\n\", ppu.read(0x2010));\n    }\n    if (t == 4) {\n        bus.write(0x0001, 0x77);\n        std::printf(\"RAM %02X, cartridge\", bus.read(0x0801));\n        std::printf(\" %02X\", bus.read(0x8000));\n        std::printf(\" %02X\\n\", bus.read(0xC123));\n    }\n}\n",
