   "main": "// Opcode's PPU timeline. Provided by the course.\n// It ticks your PPU through two frames with NMIs turned on, and prints\n// every moment something happens.\n// Program input: the value written to PPUCTRL first (default 80: NMI on).\n#include <cstdint>\n#include <cstdio>\n#include <fstream>\n#include <iostream>\n#include <iterator>\n#include <vector>\n#include \"cart.h\"\n#include \"ppu.h\"\n\nnamespace {\n\n// Read a whole file into memory. Empty if it cannot be read.\nstd::vector<std::uint8_t> read_file(const char* name) {\n    std::ifstream f(name, std::ios::binary);\n    return std::vector<std::uint8_t>(std::istreambuf_iterator<char>(f), std::istreambuf_iterator<char>());\n}\n\nconst char* result_name(LoadResult r) {\n    switch (r) {\n    case LoadResult::Ok: return \"Ok\";\n    case LoadResult::NotInes: return \"NotInes\";\n    case LoadResult::TooShort: return \"TooShort\";\n    case LoadResult::UnsupportedMapper: return \"UnsupportedMapper\";\n    }\n    return \"an unknown result\";\n}\n\n// Read game.nes and plug it into cart. Prints a message and returns false\n// if that does not work.\nbool plug_in_cartridge(Cartridge& cart) {\n    std::vector<std::uint8_t> data = read_file(\"game.nes\");\n    if (data.empty()) {\n        std::printf(\"Could not read the cartridge file.\\n\");\n        return false;\n    }\n    LoadResult r = cart.load(data);\n    if (r == LoadResult::UnsupportedMapper) {\n        int mapper = data.size() >= 8 ? ((data[7] & 0xF0) | (data[6] >> 4)) : -1;\n        std::printf(\"This cartridge uses mapper %d, which your emulator does not have yet.\\n\", mapper);\n        return false;\n    }\n    if (r != LoadResult::Ok) {\n        std::printf(\"Cartridge::load could not read this cartridge (it returned LoadResult::%s).\\n\", result_name(r));\n        return false;\n    }\n    return true;\n}\n\n}  // namespace\n\nint main() {\n    Cartridge cart;\n    if (!plug_in_cartridge(cart)) return 1;\n    Ppu ppu(cart);\n    ppu.reset();\n    unsigned ctrl = 0x80;\n    if (!(std::cin >> std::hex >> ctrl)) ctrl = 0x80;\n    ppu.register_write(0, static_cast<std::uint8_t>(ctrl));\n    std::printf(\"PPUCTRL = %02X\\n\", ctrl & 0xFF);\n    long dots = 0;\n    int frames = 0;\n    while (frames < 2 && dots < 400000) {\n        int sl = ppu.scanline(), d = ppu.dot();\n        ppu.tick();\n        dots++;\n        if (ppu.take_nmi()) std::printf(\"dot %6ld  (scanline %3d, dot %3d): NMI\\n\", dots, sl, d);\n        if (ppu.take_frame()) {\n            frames++;\n            std::printf(\"dot %6ld  (scanline %3d, dot %3d): frame %d finished\\n\", dots, sl, d, frames);\n        }\n        if (sl == 250 && d == 0) {\n            std::printf(\"dot %6ld  (scanline 250): PPUSTATUS reads %02X\", dots, ppu.register_read(2));\n            std::printf(\", then %02X\\n\", ppu.register_read(2));\n        }\n    }\n    std::printf(\"Two frames took %ld dots.\\n\", dots);\n}\n",
